'use strict';
window.FinanceEvolution=(()=>{
 const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;},eu=x=>x===null?'Sem dados':new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(x/100),pct=x=>x===null?'—':new Intl.NumberFormat('pt-PT',{maximumFractionDigits:1}).format(x)+'%';
 function render(ctx){
  const asOf=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Lisbon'}).format(new Date()),input={...ctx,asOf,throughMonth:ctx.month},flows=FinanceEvolutionModel.flow(input),wealth=FinanceEvolutionModel.wealth(input),current=flows.find(x=>x.month===(ctx.month==='all'?asOf.slice(0,7):ctx.month)),last=wealth.at(-1);
  $('analysis-income-real').textContent=current?eu(current.income):'Sem dados';$('analysis-income-result').textContent=current?eu(current.result):'Sem dados';$('analysis-consumption').textContent=current?pct(current.consumption):'—';
  $('analysis-income-caveat').textContent=current?'Entradas por confirmar: '+eu(current.unknownIn)+'. Débitos por confirmar: '+eu(current.unknownOut)+'. Transferências internas e aplicações ficam fora desta comparação. O resultado é provisório enquanto houver movimentos por rever.':'Selecione um mês com movimentos disponíveis.';
  $('evolution-scope').textContent=ctx.scopeLabel+' · histórico até '+(ctx.month==='all'?asOf.slice(0,7):ctx.month)+'. O mês atual está em curso.';
  const labels=Object.fromEntries(flows.map((m,i)=>[i+1,m.month]));
  FinancePlanning.lineChart('flow-history',[{name:'Rendimentos identificados',color:'#638742',points:flows.flatMap((m,i)=>m.income===null?[]:[{x:i+1,y:m.income,label:m.month}])},{name:'Despesa líquida',color:'#173D35',points:flows.flatMap((m,i)=>m.spending===null?[]:[{x:i+1,y:m.spending,label:m.month}])}],'Meses · consulte a cobertura na tabela',labels);
  $('flow-month-rows').replaceChildren();for(const m of [...flows].reverse()){const tr=el('tr');tr.append(el('td',m.month+(m.partial?' · parcial':'')),el('td',eu(m.income),'number'),el('td',eu(m.spending),'number'),el('td',eu(m.result),'number'),el('td',pct(m.consumption),'number'),el('td','Entradas '+eu(m.unknownIn)+' / débitos '+eu(m.unknownOut)),el('td',(m.coverage?'Coberto até '+m.end:'Cobertura incompleta')+' · '+m.review+' por rever'));$('flow-month-rows').append(tr);}
  const wealthLabels=Object.fromEntries(wealth.map((m,i)=>[i+1,m.month]));FinancePlanning.lineChart('wealth-history',[{name:'Últimos ativos documentados · inclui valores anteriores',color:'#173D35',points:wealth.flatMap((m,i)=>m.total===null||m.missing.length?[]:[{x:i+1,y:m.total,label:m.month}])}],'Meses · datas e valores transitados na tabela',wealthLabels);
  $('wealth-total').textContent=last?eu(last.total):'Sem dados';$('wealth-cash').textContent=last?eu(last.cash):'Sem dados';$('wealth-invested').textContent=last?eu(last.invested):'Sem dados';
  $('wealth-current-note').textContent=last?(last.complete?'Todas as componentes têm referência neste mês.':'Leitura parcial: '+last.missing.length+' componentes sem valor e '+last.carried.length+' com referência anterior ou cobertura insuficiente.')+' Não é património líquido: faltam imóveis, outros bens e dívidas.':'Ainda não há documentos suficientes.';
  $('wealth-month-rows').replaceChildren();for(const m of [...wealth].reverse()){const tr=el('tr'),details=el('td');for(const p of m.components)details.append(el('small',p.label+': '+eu(p.value)+(p.date?' · '+p.date:'')+(p.carried?' · transitado':'')));tr.append(el('td',m.month),el('td',eu(m.cash),'number'),el('td',eu(m.invested),'number'),el('td',eu(m.total),'number'),el('td',m.known+'/'+m.expected+(m.complete?' · referências do mês':' · parcial')),details);$('wealth-month-rows').append(tr);}
  $('classification-quality').textContent=ctx.rows.filter(r=>AccountReports.matches(r,ctx.accounts,ctx.bank,ctx.accountId)&&r.booked_on<=asOf).filter(r=>!r.category).length+' movimentos sem categoria neste âmbito. As correções manuais têm prioridade; descrições ambíguas continuam por confirmar.';
 }
 return {render};
})();
